 let full=rows.length, matched=r.length;const toolbar=`<div class="v14-table-tools"><label>搜索 <input data-v14-search="${tid}" value="${esc(search)}" placeholder="搜索当前表" aria-label="搜索表格"/></label><button class="v14-plain" data-v14="cols" data-v14-table="${tid}">列设置 ▾</button><label>每页 <select data-v14-per="${tid}">${[10,25,50].map(n=>`<option ${n===per?'selected':''}>${n}</option>`).join('')}</select></label><span class="v14-counter">匹配 ${matched} / 全量 ${full} 行</span><button class="v14-plain" data-v14="export-table" data-v14-table="${tid}">导出筛选全量 CSV</button></div>`;
