 let thead=active.map(c=>{let s=sorting.find(x=>x.field===c.field);return `<th><button class="v14-th" data-v14="sort" data-v14-table="${tid}" data-v14-field="${esc(c.field)}">${esc(c.label)} ${s?s.dir===1?'▲':'▼':'↕'}</button></th>`}).join('');
